#!/bin/bash
# Copy the BrewberryPi brand files the device web interface uses from the
# brand's home, tinkerius/brewberrypi (brand/ and site/fonts/, generated by
# its brand/tools/build_brand.py), into the brewberry-web layer. Don't edit
# the copies by hand: change the brand there, then run this again.
#
# Usage: scripts/sync-brand.sh [<checkout of tinkerius/brewberrypi>] [<ref>]
#        (default: a fresh shallow clone of main)
set -euo pipefail

# shellcheck source=scripts/common.sh
. "$(dirname "$0")/common.sh"

BRAND_REPO=https://github.com/tinkerius/brewberrypi.git
DEST=$REPO_ROOT/layer/brewberry-web.rootfs-overlay/usr/lib/brewberry-web/static
FILES="brand/logo.svg brand/logo-dark.svg brand/logo-stacked.svg brand/logo-stacked-dark.svg
   brand/favicon.svg brand/favicon.ico brand/apple-touch-icon.png
   site/fonts/zilla-slab-medium.woff2 site/fonts/OFL.txt"

src=${1:-}
ref=${2:-}
if [ -z "$src" ]; then
   src=$(mktemp -d)
   trap 'rm -rf "$src"' EXIT
   git clone --quiet --depth 1 "$BRAND_REPO" "$src"
   ref=HEAD
fi
ref=${ref:-$(git -C "$src" rev-parse --abbrev-ref HEAD)}
mkdir -p "$DEST"
for f in $FILES; do
   git -C "$src" show "$ref:$f" > "$DEST/${f##*/}"
done
echo "copied $(wc -w <<< "$FILES") brand files from $BRAND_REPO@$(git -C "$src" rev-parse --short "$ref") to ${DEST#"$REPO_ROOT"/}"
